import json, subprocess, urllib.request

def req(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(
        f"https://www.googleapis.com/calendar/v3/{path}",
        data=data, method=method,
        headers={"Authorization": "***", "Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(r) as resp:
            return resp.status, json.load(resp)
    except urllib.error.HTTPError as e:
        return e.code, json.load(e)

# 1) List calendars and find the exact target
status, d = req("GET", "users/me/calendarList?showHidden=true")
target = None
for c in d.get("items", []):
    if c.get("summary") == "APAC team" and c.get("accessRole") == "writer" and not c.get("hidden"):
        target = c
assert target, "target calendar not found"
cal_id = target["id"]
print("Target id:", repr(cal_id))

# 2) Patch the display name
status, res = req("PATCH", f"users/me/calendarList/{cal_id}", {"summaryOverride": "APAC team 2018"})
print("PATCH status:", status)
print(json.dumps(res, indent=2))

# 3) Verify
status, d2 = req("GET", "users/me/calendarList")
for c in d2.get("items", []):
    if c.get("id") == cal_id:
        print("Verified -> summary:", c.get("summary"), "| override:", c.get("summaryOverride"), "| role:", c.get("accessRole"))
EOF

